 enum class Service:uint8_t{None,Gate,Edit,Display,ParameterControl,ParameterMode,ParameterMenu};struct Request{Service service=Service::None;uint8_t delta=0,mode=0;};enum class Block:uint8_t{None,NotBound,Inactive,NeedsInterrupt,UnsupportedMode,AwaitService};struct Result{unsigned clocks=0;bool returned=false;Block blocked=Block::None;};struct Range{uint32_t begin,end;};inline static constexpr std::array<Range,1>CodeRanges{{{0x3b6e,0x3bd6}}};
 bool bindVerifiedFirmware(ControllerDeviceState&d,const uint8_t*image,size_t size){if(bound_||active()||!image||size!=49728||!d.hasImmutableCapacity(2))return false;for(auto r:CodeRanges)for(auto a=r.begin;a<r.end;++a)if(d.readResource(a)!=image[a]||d.readResource(0x400000+a)!=image[a])return false;for(auto r:CodeRanges)if(!d.protectImmutableVerified(r.begin,r.end,image+r.begin)||!d.protectImmutableVerified(0x400000+r.begin,0x400000+r.end,image+r.begin))return false;if(!encoder_.bindVerifiedFirmware(d,image,size))return false;if(!mode_.bindVerifiedFirmware(d,image,size))return false;bound_=&d;return true;}
 bool boundTo(const ControllerDeviceState&d)const{return bound_==&d;}bool active()const{return task_.has_value();}bool start(){if(!bound_||active())return false;task_.emplace();return true;}void reset(){task_.reset();encoder_.reset();request_={};mode_.reset();}Request request()const{return request_;}
